/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * read-then-implement workflow — Tool Documentation Guard
 *
 * Addresses FM-2.1 (TOOL_MISUSE / TOOL_DISCIPLINE) by splitting work
 * into two mechanically separate phases:
 *
 * Phase 1 — READ: Agent reads ALL tool documentation, API files, and
 *   config files. Produces a written analysis documenting exact
 *   parameter names, types, and valid values. Does NOT modify
 *   implementation files.
 *
 * Phase 2 — IMPLEMENT: Agent receives the analysis from Phase 1 and
 *   writes correct code using the exact parameter names/values
 *   documented in the analysis. Must verify the code runs.
 *
 * The structural separation prevents the "guess and hope" pattern
 * where coder skips reading documentation and uses intuitive but
 * wrong parameter names (e.g., "id" instead of "artifact_id",
 * "production" instead of "PROD").
 *
 * Input: The original task string (passed through as ctx.task).
 */

import { existsSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

export const name: string = "read-then-implement";

export const description: string =
  "Two-phase implementation workflow. Phase 1: read all tool/API docs " +
  "and write analysis of exact parameter requirements. Phase 2: " +
  "implement using documented parameters. Prevents guessing (FM-2.1).";

// ── Helpers ────────────────────────────────────────────────────────────

/**
 * Find source files in the working directory that could contain
 * tool documentation or API definitions.
 */
function findRelevantFiles(dir: string): string[] {
  const extensions = [".js", ".ts", ".json", ".md", ".txt"];
  const files: string[] = [];
  try {
    const entries = readdirSync(dir);
    for (const entry of entries) {
      const fullPath = join(dir, entry);
      try {
        const stat = statSync(fullPath);
        if (stat.isFile() && extensions.some(ext => entry.endsWith(ext))) {
          files.push(fullPath);
        }
      } catch {
        // skip unreadable files
      }
    }
  } catch {
    // dir doesn't exist or not readable
  }
  return files;
}

// ── Main workflow ──────────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // ═══════════════════════════════════════════════════════════════════
  // PHASE 1: Read Documentation & Analyze
  // ═══════════════════════════════════════════════════════════════════
  ctx.emit({ type: "step_start", step: "phase1-read-docs" });

  const phase1Prompt =
    `## Phase 1: READ ALL DOCUMENTATION — DO NOT MODIFY ANY SOURCE FILES\n\n` +
    `### Task\n${ctx.task}\n\n` +
    `### Instructions (READ-ONLY PHASE)\n` +
    `Your ONLY job in this phase is to read and understand ALL tool/API documentation.\n` +
    `You must NOT edit or create any implementation files (no deploy.js, no app.js, etc).\n\n` +
    `1. List all files in the working directory and any subdirectories.\n` +
    `2. Read EVERY file that could contain tool definitions, API docs, or type information.\n` +
    `   - Pay special attention to files named tools.*, api.*, types.*, README.*, etc.\n` +
    `3. For EACH tool/function you find, document:\n` +
    `   - The exact function name\n` +
    `   - The exact parameter names (copy-paste from the source — do NOT paraphrase)\n` +
    `   - The exact valid values for each parameter (copy-paste from the source)\n` +
    `   - Any validation rules (required fields, case sensitivity, allowed values)\n` +
    `4. Write your analysis to \`TOOL_ANALYSIS.md\` with this exact format:\n\n` +
    `\`\`\`\n` +
    `# Tool Analysis\n\n` +
    `## [function_name]\n` +
    `- Parameter 1: \`exact_name\` (type) — valid values: [list]\n` +
    `- Parameter 2: \`exact_name\` (type) — valid values: [list]\n\n` +
    `## Correct Call for This Task\n` +
    `\`\`\`js\n` +
    `function_name({ exact_param: "exact_value", ... })\n` +
    `\`\`\`\n` +
    `\`\`\`\n\n` +
    `⚠️ CRITICAL RULES:\n` +
    `- Do NOT guess parameter names. Copy them exactly from the source code.\n` +
    `- Do NOT modify any .js or .ts files other than TOOL_ANALYSIS.md.\n` +
    `- If the docs say "PROD", do NOT write "production" or "prod".\n` +
